-- Phase 54: governed reporting metadata. Analytical facts and Metric Catalog remain the source of truth.
alter table public.plans add column if not exists advanced_reporting_enabled boolean not null default true,add column if not exists report_builder_enabled boolean not null default false,add column if not exists scheduled_reports_enabled boolean not null default false,add column if not exists report_exports_enabled boolean not null default false,add column if not exists report_ai_builder_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists advanced_reporting_enabled boolean not null default true,add column if not exists report_builder_enabled boolean not null default false,add column if not exists scheduled_reports_enabled boolean not null default false,add column if not exists report_exports_enabled boolean not null default false,add column if not exists report_ai_builder_enabled boolean not null default false;

create table public.report_dataset_registry(
 id text primary key,name text not null,description text not null,source text not null check(source in('warehouse','hybrid','operational')),available_metrics text[] not null default '{}',available_dimensions text[] not null default '{}',available_filters text[] not null default '{}',supported_time_granularity text[] not null default '{}',required_permissions text[] not null default '{reports:view}',realtime_or_analytical text not null check(realtime_or_analytical in('realtime','analytical','hybrid')),sensitivity text not null default 'normal' check(sensitivity in('normal','pii','financial','restricted')),column_policy jsonb not null default '{}',schema_version integer not null default 1,active boolean not null default true,updated_at timestamptz not null default now()
);
comment on table public.report_dataset_registry is 'Semantic datasets only; never maps client input to arbitrary physical tables.';
create table public.report_dimension_registry(
 id text primary key,name text not null,data_type text not null,filter_operators text[] not null default '{}',sensitive boolean not null default false,view_permission text,export_permission text,masking_policy text,active boolean not null default true
);
create table public.report_definitions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,owner_user_id uuid not null references auth.users(id) on delete restrict,name text not null check(length(btrim(name)) between 2 and 120),description text,report_type text not null check(report_type in('table','summary','grouped_table','pivot','trend','comparison','operational','executive')),dataset_id text not null references public.report_dataset_registry(id),status text not null default 'draft' check(status in('draft','active','archived','invalid')),version integer not null default 1 check(version>0),scope text not null default 'store' check(scope in('store','organization','network')),visibility text not null default 'private' check(visibility in('private','team','store','organization','network')),definition_json jsonb not null default '{}',store_id uuid references public.establishments(id) on delete cascade,team_id text,confidential boolean not null default false,is_favorite boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.report_definition_versions(
 id uuid primary key default gen_random_uuid(),report_definition_id uuid not null references public.report_definitions(id) on delete cascade,version integer not null,status text not null check(status in('draft','published','superseded')),definition_json jsonb not null,change_summary text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),published_at timestamptz,unique(report_definition_id,version)
);
create table public.report_shares(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,report_definition_id uuid not null references public.report_definitions(id) on delete cascade,shared_with_user_id uuid references auth.users(id) on delete cascade,shared_with_role text,permissions text[] not null default '{view}',store_id uuid references public.establishments(id) on delete cascade,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(shared_with_user_id is not null or shared_with_role is not null)
);
create table public.report_executions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,report_definition_id uuid references public.report_definitions(id) on delete set null,version integer not null default 1,requested_by uuid references auth.users(id) on delete set null,status text not null default 'queued' check(status in('queued','running','completed','failed','expired','cancelled')),started_at timestamptz,completed_at timestamptz,parameters jsonb not null default '{}',scope_snapshot jsonb not null default '{}',row_count integer,result_location text,error_code text,diagnostic_id uuid not null default gen_random_uuid(),data_as_of timestamptz,source_freshness jsonb not null default '{}',query_plan jsonb not null default '{}',cache_key text,expires_at timestamptz,created_at timestamptz not null default now()
);
create table public.report_execution_jobs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,execution_id uuid not null unique references public.report_executions(id) on delete cascade,priority smallint not null default 50 check(priority between 1 and 100),status text not null default 'pending' check(status in('pending','leased','completed','failed','cancelled')),attempts integer not null default 0,max_attempts integer not null default 3,available_at timestamptz not null default now(),leased_until timestamptz,last_error text,idempotency_key text not null,created_at timestamptz not null default now(),unique(organization_id,idempotency_key)
);
create table public.report_result_cache(
 organization_id uuid not null references public.organizations(id) on delete cascade,cache_key text not null,report_version integer not null,result_json jsonb not null default '{}',row_count integer not null default 0,data_as_of timestamptz not null,source_freshness jsonb not null default '{}',expires_at timestamptz not null,created_at timestamptz not null default now(),primary key(organization_id,cache_key)
);
create table public.report_exports(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,report_execution_id uuid not null references public.report_executions(id) on delete cascade,format text not null check(format in('csv','xlsx','pdf')),status text not null default 'queued' check(status in('queued','generating','ready','failed','expired')),file_id text,storage_path text,created_by uuid references auth.users(id) on delete set null,sensitive boolean not null default false,row_count integer,download_count integer not null default 0,expires_at timestamptz not null,created_at timestamptz not null default now()
);
create table public.report_schedules(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,report_definition_id uuid not null references public.report_definitions(id) on delete cascade,name text not null,recurrence text not null check(recurrence in('daily','weekly','monthly')),safe_schedule jsonb not null default '{}',timezone text not null,parameters jsonb not null default '{}',output_format text not null check(output_format in('link','csv','xlsx','pdf')),destination_type text not null check(destination_type in('in_app','email')),recipients jsonb not null default '[]',status text not null default 'active' check(status in('active','paused','error','archived')),next_run_at timestamptz,last_run_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.report_deliveries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,schedule_id uuid references public.report_schedules(id) on delete set null,execution_id uuid not null references public.report_executions(id) on delete cascade,recipient jsonb not null,channel text not null check(channel in('in_app','email')),status text not null default 'queued' check(status in('queued','sending','sent','failed','dead_lettered')),attempts integer not null default 0,max_attempts integer not null default 3,available_at timestamptz not null default now(),sent_at timestamptz,error_code text,idempotency_key text not null,created_at timestamptz not null default now(),unique(organization_id,idempotency_key)
);
create table public.report_templates(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,name text not null,description text not null default '',category text not null,dataset_id text not null references public.report_dataset_registry(id),definition_json jsonb not null,system_template boolean not null default false,read_only boolean not null default false,required_permissions text[] not null default '{reports:view}',widget_compatible boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.report_favorites(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,report_definition_id uuid not null references public.report_definitions(id) on delete cascade,created_at timestamptz not null default now(),primary key(organization_id,user_id,report_definition_id));
create table public.report_recent_views(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,report_definition_id uuid not null references public.report_definitions(id) on delete cascade,viewed_at timestamptz not null default now(),primary key(organization_id,user_id,report_definition_id));
create table public.report_snapshots(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,report_definition_id uuid not null references public.report_definitions(id) on delete restrict,execution_id uuid references public.report_executions(id) on delete set null,name text not null,snapshot_period jsonb not null,result_location text,result_summary jsonb not null default '{}',data_as_of timestamptz not null,created_by uuid references auth.users(id),created_at timestamptz not null default now()
);
create table public.report_snapshot_annotations(id uuid primary key default gen_random_uuid(),snapshot_id uuid not null references public.report_snapshots(id) on delete cascade,author_user_id uuid references auth.users(id) on delete set null,body text not null check(length(body) between 1 and 1000),created_at timestamptz not null default now());
create table public.report_ai_drafts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,prompt_redacted text not null,definition_json jsonb not null,validation_errors jsonb not null default '[]',status text not null default 'draft' check(status in('draft','accepted','discarded')),created_at timestamptz not null default now());
create table public.report_audit_events(
 id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_user_id uuid references auth.users(id) on delete set null,report_definition_id uuid references public.report_definitions(id) on delete set null,execution_id uuid references public.report_executions(id) on delete set null,export_id uuid references public.report_exports(id) on delete set null,action text not null,sensitive boolean not null default false,before_state jsonb,after_state jsonb,reason text,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now()
);
create table public.report_usage_hourly(organization_id uuid not null references public.organizations(id) on delete cascade,bucket_at timestamptz not null,executions bigint not null default 0,failures bigint not null default 0,latency_ms_sum bigint not null default 0,queue_lag_ms_sum bigint not null default 0,exports bigint not null default 0,export_generation_ms_sum bigint not null default 0,warehouse_query_ms_sum bigint not null default 0,cache_hits bigint not null default 0,cache_misses bigint not null default 0,primary key(organization_id,bucket_at));

create index report_definitions_scope_idx on public.report_definitions(organization_id,owner_user_id,status,dataset_id,visibility);
create index report_definitions_store_idx on public.report_definitions(organization_id,store_id,status,updated_at desc);
create index report_executions_status_idx on public.report_executions(organization_id,report_definition_id,status,started_at desc);
create index report_jobs_due_idx on public.report_execution_jobs(status,priority desc,available_at) where status='pending';
create index report_exports_expiry_idx on public.report_exports(status,expires_at);
create index report_schedules_due_idx on public.report_schedules(status,next_run_at) where status='active';
create index report_deliveries_due_idx on public.report_deliveries(status,available_at) where status in('queued','failed');
create index report_audit_org_idx on public.report_audit_events(organization_id,created_at desc);

