insert into public.notification_source_registry(id,event_type,category,source_type,title_template,summary_template,priority_rules,allowed_actions,default_recipient_rules,dedup_strategy,grouping_strategy,expiration_strategy) values
('report-ready','report.ready','reporting','report_execution','Relatório pronto','A execução do relatório foi concluída.','{"default":"info"}','["open","acknowledge"]','["requested_by"]','{"key":"execution:recipient"}','{}','{"expires_hours":168}')
on conflict(event_type) do update set title_template=excluded.title_template,summary_template=excluded.summary_template,allowed_actions=excluded.allowed_actions;

do $$ declare t text; begin foreach t in array array['report_dataset_registry','report_dimension_registry','report_definitions','report_definition_versions','report_shares','report_executions','report_execution_jobs','report_result_cache','report_exports','report_schedules','report_deliveries','report_templates','report_favorites','report_recent_views','report_snapshots','report_snapshot_annotations','report_ai_drafts','report_audit_events','report_usage_hourly'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.report_dataset_registry,public.report_dimension_registry,public.report_templates to authenticated;
create policy report_dataset_authenticated_read on public.report_dataset_registry for select to authenticated using(active);
create policy report_dimension_authenticated_read on public.report_dimension_registry for select to authenticated using(active);
create policy report_templates_scope_read on public.report_templates for select to authenticated using(active and (organization_id is null or organization_id in(select om.organization_id from public.organization_members om where om.user_id=(select auth.uid()) and om.active)));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('report-exports','report-exports',false,52428800,array['text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

